{"code": "import pandas as pd, statsmodels.formula.api as smf
df=pd.read_csv('data/explore.csv')
ex=['canopy_cover','soil_moisture','elevation_m','road_dist_km','leaf_litter','temperature_c','slope_deg','nitrate','grazing_index','rainfall_mm']
for e in ex:
    m=smf.ols(f'species_richness~{e}+C(region)',df).fit()
    print(e, round(m.params[e],3), round(m.pvalues[e],4))"}
